                } while (next_permutation(v.begin(), v.end()));
                ++nump;
            }

    for (int mask = 0; mask < (1 << 18); ++mask) {
        ll v = 1;
        for (int i = 0; i < 18; ++i) {
            if ((mask >> i) & 1)
                v = v * p[E[i].first][E[i].second] % mod;
            else
                v = v * (mod + 1 - p[E[i].first][E[i].second]) % mod;
        }
        F[m[mask]] = (F[m[mask]] + v) % mod;
    }

    for (int i = 0; i < 20; ++i)
        for (int mask = 0; mask < (1 << 20); ++mask)
            if (mask & (1 << i))
                F[mask] = (F[mask] + F[mask ^ (1 << i)]) % mod;

    vector<int> m2(1 << 18, 0);
    vector<ll> ans(1 << 20, 0);
    for (int i = 0; i < 6; ++i)
